import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { transform } from '@diplodoc/transform';
import { MarkdownEditorView, useMarkdownEditor, type MarkupString, YfmStaticView } from '@gravity-ui/markdown-editor';
import { Button, Card, Flex, Text, TextInput } from '@gravity-ui/uikit';

interface SubmittedMessage {
  author: string;
  markdown: string;
}

export function App() {
  const [author, setAuthor] = useState('');
  const [submittedMessages, setSubmittedMessages] = useState<SubmittedMessage[]>([]);

  const editor = useMarkdownEditor({
    allowHTML: false,
    initial: {
      mode: 'wysiwyg',
    },
    md: {
      breaks: true,
      linkify: true,
    },
  });

  const handleSubmit = useCallback(() => {
    const markdown = editor.getValue();
    if (author.trim() === '' || markdown.trim() === '') {
      return;
    }

    setSubmittedMessages((messages) => [
      { author: author.trim(), markdown },
      ...messages,
    ]);
  }, [author, editor]);

  return (
    <Flex direction=\"column\" gap={5} width=\"100%\" maxWidth={760} spacing={{ px: 4, py: 5 }}>
      <Text variant=\"display-2\" as=\"h1\">
        Добавить сообщение
      </Text>

      <Card>
        <Flex direction=\"column\" gap={4} spacing={{ p: 5 }}>
          <TextInput
            label=\"Автор\"
            placeholder=\"Имя автора\"
            size=\"l\"
            value={author}
            onUpdate={setAuthor}
          />

          <Flex direction=\"column\" gap={3}>
            <Text variant=\"subheader-1\" as=\"label\">
              Текст сообщения
            </Text>
            <MarkdownEditorView editor={editor} stickyToolbar autofocus />
          </Flex>

          <Flex gap={3} justifyContent=\"flex-end\">
            <Button view=\"action\" size=\"l\" disabled={author.trim() === ''} onClick={handleSubmit}>
              Отправить
            </Button>
          </Flex>
        </Flex>
      </Card>

      {submittedMessages.map((message, index) => (
        <Card key={"'`${message.author}-${index}`}>
          <Flex direction="column" gap={2} spacing={{ p: 4 }}>
            <Text variant="subheader-1">{message.author}</Text>
            <MarkdownStaticView markdown={message.markdown} />
          </Flex>
        </Card>
      ))}
    </Flex>
  );
}

function MarkdownStaticView({ markdown }: { markdown: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const html = useMemo(() => transform(markdown, { allowHTML: false, breaks: true, linkify: true }).result.html, [markdown]);

  useEffect(() => {
    void ref.current;
  }, [html]);

  return <YfmStaticView ref={ref} html={html} noListReset />;
}
